import {readFileSync,writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
const dir=process.argv[2];if(!dir)throw Error('Expected diagnostic directory');
const hash=path=>createHash('sha256').update(readFileSync(path)).digest('hex');
const json=path=>JSON.parse(readFileSync(path,'utf8'));
const providerModules={
 control:['backend_lower','c_backend','c_backend_layout','c_backend_link','c_backend_physical','c_emit_core','descriptor_nf','js_backend','js_emit','lower_catalog'],
 candidate:['backend_lower','backend_transport','c_backend','c_backend_layout','c_backend_link','c_backend_physical','c_emit_core','descriptor_nf','js_backend','js_emit','lower_catalog']
};
function sourceIndex(path,map,providers){
 const index=new Map();let owner=null;
 // js_backend.code emits its function followed by conts(body,ctx), then the
 // next Code. Only explicit function declarations are joined; public arrows,
 // anonymous BIR codes and numeric-id differences remain unassigned.
 for(const line of readFileSync(path,'utf8').split('\n')){
  const match=/^function (\$[bkr][A-Za-z0-9_]*)\(/.exec(line);if(!match)continue;
  const name=match[1];if(/^\$b\d+$/.test(name))owner=name;
  const key=map[name]??(/^\$[kr]/.test(name)?map[owner]:null);
  const provider=key&&/(?:^|\.)emitter_body_cps_provider_(\d+)_/.exec(key);
  const providerId=provider?Number(provider[1]):null;
  index.set(name,{owner,key:key??null,provider:providerId,module:providerId?providers[providerId-1]??null:null});
 }
 return index;
}
function frameOwner(frame,index){return index.get(frame.functionName)?.module??null;}
function add(map,key,value){map.set(key,(map.get(key)??0)+value);}
function classifyCpu(path,index){
 const p=json(path),nodes=new Map(p.nodes.map(n=>[n.id,n])),parents=new Map(),byOwner=new Map(),bySelf=new Map(),top=new Map();
 for(const n of p.nodes)for(const child of n.children??[])parents.set(child,n.id);
 if(p.samples.length!==p.timeDeltas.length)throw Error('CPU sample/delta mismatch');let total=0;const negativeDeltas=[];
 for(let i=0;i<p.samples.length;i++){
  const delta=p.timeDeltas[i];if(!Number.isFinite(delta))throw Error('Nonfinite CPU delta');if(delta<0)negativeDeltas.push({index:i,deltaUs:delta});const weight=1;total+=weight;
  let id=p.samples[i],nearest=null;const first=nodes.get(id);if(!first)throw Error('Missing sampled node');
  const selfKey=first.callFrame.functionName==='(garbage collector)'?'gc':first.callFrame.url==='node:inspector'?'inspector':frameOwner(first.callFrame,index)??'unassigned';add(bySelf,selfKey,weight);
  const identity=JSON.stringify(first.callFrame),row=top.get(identity)??{frame:first.callFrame,selfSamples:0};row.selfSamples+=weight;top.set(identity,row);
  const seen=new Set();while(id!==undefined){if(seen.has(id))throw Error('CPU parent cycle');seen.add(id);const n=nodes.get(id);nearest=frameOwner(n.callFrame,index);if(nearest)break;id=parents.get(id);}
  add(byOwner,selfKey==='gc'||selfKey==='inspector'?selfKey:nearest??'unassigned',weight);
 }
 return {path,sha256:hash(path),samples:p.samples.length,negativeDeltas,weighting:'Unweighted sample counts in both roles; no sample dropped or interval clamped. Original timeDeltas retained in raw profiles; candidate has a negative interval, so duration-weighted attribution is not used.',selfBySource:Object.fromEntries(bySelf),nearestSourceOnStack:Object.fromEntries([...byOwner].map(([k,v])=>[k,{samples:v,share:v/total}])),topSelf:[...top.values()].sort((a,b)=>b.selfSamples-a.selfSamples).slice(0,20)};
}
function classifyAllocation(path,index){
 const p=json(path),pending=[[p.head,null]],byOwner=new Map(),bySelf=new Map(),top=new Map();let total=0;
 while(pending.length){const [node,parentOwner]=pending.pop();if(!node?.callFrame||!Number.isFinite(node.selfSize)||node.selfSize<0)throw Error('Bad allocation node');
  const own=frameOwner(node.callFrame,index),owner=own??parentOwner;total+=node.selfSize;add(byOwner,owner??'unassigned',node.selfSize);add(bySelf,own??'unassigned',node.selfSize);
  const key=JSON.stringify(node.callFrame),row=top.get(key)??{frame:node.callFrame,estimatedBytes:0};row.estimatedBytes+=node.selfSize;top.set(key,row);
  for(const child of node.children)pending.push([child,owner]);
 }
 return {path,sha256:hash(path),estimatedBytes:total,selfBySource:Object.fromEntries(bySelf),nearestSourceOnStack:Object.fromEntries([...byOwner].map(([k,v])=>[k,{estimatedBytes:v,share:total?v/total:0}])),top:[...top.values()].sort((a,b)=>b.estimatedBytes-a.estimatedBytes).slice(0,15)};
}
const report={schemaVersion:1,status:'PAIRED_REAL_EMIT_PROFILE_ANALYSIS',diagnosticOnly:true,compilerAccepted:false,performanceAccepted:false,method:{continuationOwnership:'js_backend.code emits code function then conts(body,ctx) before next code; verified source anchors bend2/selfhost/js_backend.bend:847-856 and 1386-1392. Only named declarations and their emitted continuations are joined through the same-line $D sidecar.',cpu:'timeDelta-weighted V8 samples; nearest source provider present on a sampled synchronous stack. Unkeyed code and CPS-erased ancestry stay unassigned.',allocation:'Sum sampled selfSize once per allocation tree node; nearest source provider on the retained allocation stack. Not exact allocated bytes or retained memory.',chunks:'Pending request constructor at 64-step boundaries; not durations, per-definition calls or precise stage boundaries.'},roles:[]};
report.method.cpu='Unweighted V8 CPU sample counts for both roles; nearest source provider present on a sampled synchronous stack. One recorded negative interval makes duration-weighted attribution unsuitable; no interval is clamped and no sample is dropped. Unkeyed code and CPS-erased ancestry stay unassigned.';
for(const role of ['control','candidate']){
 const path=dir+'/'+role+'-emit.result.json',r=json(path);if(r.status!=='G33_EMIT_DIAGNOSTIC_COMPLETED'||!r.output?.matchesExpected||r.own?.driver?.sha256!=='6829835e9592cc25c469cb16dc3cdbbf8be7bf852c23783ad4c1d85e15db2ed8')throw Error('Invalid emit report '+role);
 const attribution=json(r.attribution.path),imagePath=r.target.image.path,index=sourceIndex(imagePath,attribution.map,providerModules[role]);
 report.roles.push({role,report:{path,sha256:hash(path)},own:r.own,moduleResidency:r.moduleResidency,target:r.target,stepCounts:r.stepCounts,phases:r.phases.map(({phase,elapsedMs,userCpuMs,systemCpuMs})=>({phase,elapsedMs,userCpuMs,systemCpuMs})),output:r.output,chunkAttribution:{usable:false,reason:'Request-group wrappers were not unwrapped by the diagnostic observer; pending provider counts cannot be recovered from its aggregate. CPU/allocation source ownership is analyzed separately.',observed:r.chunkAttribution},attribution:r.attribution,providerModules:providerModules[role],cpu:classifyCpu(r.emitWindow.cpuProfilePath,index),allocation:classifyAllocation(r.emitWindow.allocationProfilePath,index),gc:r.gc.windows??r.gc.totals,limitations:r.limitations});
}
writeFileSync(dir+'/emit-analysis.json',JSON.stringify(report,null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify({status:report.status,roles:report.roles.map(r=>({role:r.role,steps:r.stepCounts,phase:r.phases.find(p=>p.phase==='emit'),cpu:r.cpu.nearestSourceOnStack,allocation:r.allocation.nearestSourceOnStack,chunks:r.chunkAttribution,output:r.output}))}));

import {readFileSync,writeFileSync,realpathSync,readdirSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {dirname,resolve,isAbsolute,posix,join} from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {PerformanceObserver,performance,constants as performanceConstants} from 'node:perf_hooks';
import {getHeapStatistics,getHeapSpaceStatistics} from 'node:v8';
import {Worker,isMainThread,threadId,workerData} from 'node:worker_threads';
import {createCpuProfiler} from "/Users/ilyagulya/Projects/My/bend/evals/selfhost_cpu_profile.mjs";
import {runTemplateSteps,runCheckerSteps} from "/Users/ilyagulya/Projects/My/bend/evals/checker_core_step_runtime.mjs";

const WORKER_LIMITS=Object.freeze({stackSizeMb:256,maxOldGenerationSizeMb:6144,maxYoungGenerationSizeMb:128});
const hash=path=>createHash('sha256').update(readFileSync(path)).digest('hex'),tag=value=>typeof value?.$==='string'?value.$.split('.').at(-1):null;
const items=value=>{const out=[];while(tag(value)==='Con'){out.push(value.head);value=value.tail;}if(tag(value)!=='Nil')throw Error('Malformed native list');return out;};
const list=values=>values.reduceRight((tail,head)=>({$:'Con',head,tail}),{$:'Nil'});
const fuelEnd=Object.freeze({$:'FeedbackFuelEnd'}),fuelPrototype={get tail(){return fuel(this.remaining-1);}};
function fuel(remaining){if(remaining===0)return fuelEnd;const node=Object.create(fuelPrototype);node.$='FeedbackFuelCell';node.remaining=remaining;return node;}
const gcNodeConstants=Object.freeze(Object.fromEntries(Object.entries(performanceConstants).filter(([name])=>name.startsWith('NODE_PERFORMANCE_GC_'))));

const DRIVER_LIMITATIONS=Object.freeze([
 'Diagnostic only: this report is not timing acceptance, not memory acceptance, not compiler acceptance and not a byte-fixedpoint claim.',
 'A completed pair of reports shows observed CPU/allocation windows, host-worker GC entries and point-in-time heap statistics; any comparison remains the parent\'s separate qualification step.',
 'Each role loads exactly one actual compiler image module; parser and checker API identity is equal, matching original throughput residency.',
 'GC observation, inspector sampling and heap boundary reads all perturb the process; never use these numbers as unprofiled timing samples.',
 'No relative-memory cutoff exists in this driver and none may be derived from its output.',
]);

function verify(request){for(const [path,digest]of Object.entries({...request.inputs,...request.pins}))if(realpathSync(path)!==path||hash(path)!==digest)throw Error('Pinned input drift '+path);}

function targetIdentity(path,declared){
 const bytes=readFileSync(path),sha256=createHash('sha256').update(bytes).digest('hex');
 const identity={path,sha256,bytes:bytes.length,declaredSha256:typeof declared?.sha256==='string'?declared.sha256:null,declaredBytes:Number.isInteger(declared?.bytes)?declared.bytes:null,matchesSha256:typeof declared?.sha256==='string'?declared.sha256===sha256:null,matchesBytes:Number.isInteger(declared?.bytes)?declared.bytes===bytes.length:null};
 if(identity.matchesSha256===false||identity.matchesBytes===false)throw Error('Target image identity drift '+path);
 return identity;
}

function heapSnapshot(){return {elapsedMs:performance.now(),memoryUsage:process.memoryUsage(),heapStatistics:getHeapStatistics(),heapSpaces:getHeapSpaceStatistics().map(space=>({...space}))};}

function validateWindows(windows){
 if(!Array.isArray(windows))throw Error('Expected windows array');
 let previousEnd=-1;
 for(const [index,window] of windows.entries()){
  if(!Number.isInteger(window?.start)||!Number.isInteger(window?.end)||window.start<0||window.end<=window.start)throw Error('Invalid profiling window '+index);
  if(window.start<=previousEnd)throw Error('Profiling windows must be strictly ascending and disjoint at '+index);
  previousEnd=window.end;
 }
}

function profilerPrefix(){return `selfhost-${process.pid}-thread-${threadId}-`;}
function profileDirectories(root){
 try{return new Set(readdirSync(root).filter(name=>name.startsWith(profilerPrefix())));}
 catch(error){if(error?.code==='ENOENT')return new Set();throw error;}
}

async function screen(requestPath,reportPath){
 const request=JSON.parse(readFileSync(requestPath,'utf8'));verify(request);validateWindows(request.windows);
 const driverPath=realpathSync(fileURLToPath(import.meta.url));
 const profileRoot=resolve(request.profileDirectory);
 const report={schemaVersion:2,kind:'g33-paired-check-diagnostic',status:'RUNNING',statusMeaning:'Execution in progress; no acceptance is implied at any stage.',diagnosticOnly:true,acceptanceEvidence:false,timingAcceptance:false,compilerAccepted:false,byteFixedpoint:false,relativeMemoryCutoff:null,role:request.role,scope:'Standalone paired diagnostic on the frozen root and actual selfhost images. Each role uses one unqueried actual compiler image for parse/expand/check, capture bounded CPU/allocation windows with the existing profiler, and observe host-worker GC plus heap boundaries. Diagnostic only: not timing acceptance, memory acceptance, compiler acceptance or byte fixedpoint.',request:requestPath,requestSha256:hash(requestPath),parserImage:request.parserImage,checkerImage:request.checkerImage,target:{parser:targetIdentity(request.parserImage.path,request.parserImage),checker:targetIdentity(request.checkerImage.path,request.checkerImage),root:{path:request.root,sha256:hash(request.root)}},root:request.root,sourceSha256:hash(request.root),profileDirectory:profileRoot,own:{driver:{path:driverPath,sha256:hash(driverPath)},pid:process.pid,threadId,isMainThread,execPath:process.execPath,execArgv:process.execArgv,platform:process.platform,arch:process.arch,workerResourceLimits:WORKER_LIMITS},runtime:{execPath:process.execPath,versions:process.versions,execArgv:process.execArgv},moduleResidency:null,phases:[],stepCounts:{},windows:[],gc:null,limitations:[]};
 const save=()=>writeFileSync(reportPath,JSON.stringify(report,null,2)+String.fromCharCode(10));save();
 let profiler,windowIndex=0,gcObserver,gcObservation,gcFlush=null;
 const gcEvents=[],beforeDirs=[];
 const windowRecords=request.windows.map((window,index)=>({index,startStep:window.start,endStep:window.end,startElapsedMs:null,endElapsedMs:null,hostWallMs:null,profilerStartElapsedMs:null,profilerEndElapsedMs:null,profilerWallMs:null,profilerCpuMs:null,profilerMemoryStart:null,profilerMemoryEnd:null,profilerRunDirectory:null,profilerSummaryPath:null,profilerCpuProfilePath:null,profilerAllocationProfilePath:null,profilerSummaryStatus:'pending',heapStart:null,heapEnd:null,gc:null}));

 const phase=async(name,action)=>{
  const heapStart=heapSnapshot();
  const startElapsedMs=heapStart.elapsedMs,cpu=process.cpuUsage();
  const result=await action();
  const used=process.cpuUsage(cpu),endElapsedMs=performance.now();
  const heapEnd=heapSnapshot();
  report.phases.push({phase:name,startElapsedMs,endElapsedMs,elapsedMs:endElapsedMs-startElapsedMs,userCpuMs:used.user/1000,systemCpuMs:used.system/1000,memoryEnd:process.memoryUsage(),heap:{start:heapStart,end:heapEnd}});
  save();return result;
 };

 const attachGcObserver=()=>{
  gcObserver=new PerformanceObserver(observed=>{
   for(const entry of observed.getEntries()){
    const detail=entry.detail;
    gcEvents.push({startTime:entry.startTime,duration:entry.duration,kind:detail?detail.kind:null,flags:detail?detail.flags:null});
   }
  });
  gcObserver.observe({entryTypes:['gc']});
  return {entryTypes:['gc'],scope:'host worker isolate only',pid:process.pid,threadId,isMainThread,attachedAtElapsedMs:performance.now(),delivery:'asynchronous PerformanceObserver delivery',forcedGc:false,fullHeapSnapshot:false};
 };

 const flushGc=async()=>{
  if(gcFlush)return gcFlush;
  const eventsBefore=gcEvents.length,requestedAtElapsedMs=performance.now();
  await new Promise(resolveImmediate=>setImmediate(resolveImmediate));
  await new Promise(resolveTimeout=>setTimeout(resolveTimeout,0));
  if(gcObserver){gcObserver.disconnect();gcObserver=undefined;}
  gcFlush={method:'setImmediate then setTimeout(0)',requestedAtElapsedMs,completedAtElapsedMs:performance.now(),eventsBefore,eventsAfter:gcEvents.length,disconnectedAtElapsedMs:performance.now(),forcedGc:false,fullHeapSnapshot:false};
  return gcFlush;
 };

 const resolveProfilerSummary=record=>{
  try{
   const created=readdirSync(profileRoot,{withFileTypes:true}).filter(entry=>entry.isDirectory()&&entry.name.startsWith(profilerPrefix())&&!beforeDirs[record.index].has(entry.name));
   if(created.length!==1)throw Error('Expected exactly one new profiler run directory, observed '+created.length);
   const runDirectory=join(profileRoot,created[0].name);
   const summaries=readdirSync(runDirectory).filter(name=>/^[0-9]{6}-check-window\.json$/.test(name));
   if(summaries.length!==1)throw Error('Expected exactly one check-window profiler summary, observed '+summaries.length);
   const summaryPath=join(runDirectory,summaries[0]),summary=JSON.parse(readFileSync(summaryPath,'utf8'));
   for(const key of ['startElapsedMs','endElapsedMs','wallMs','cpuMs'])if(!Number.isFinite(summary[key]))throw Error('Profiler summary missing '+key);
   if(!summary.memoryStart||!summary.memoryEnd)throw Error('Profiler summary missing memory boundary');
   record.profilerRunDirectory=runDirectory;record.profilerSummaryPath=summaryPath;record.profilerCpuProfilePath=typeof summary.profilePath==='string'?summary.profilePath:null;record.profilerAllocationProfilePath=typeof summary.allocationProfilePath==='string'?summary.allocationProfilePath:null;record.profilerStartElapsedMs=summary.startElapsedMs;record.profilerEndElapsedMs=summary.endElapsedMs;record.profilerWallMs=summary.wallMs;record.profilerCpuMs=summary.cpuMs;record.profilerMemoryStart=summary.memoryStart;record.profilerMemoryEnd=summary.memoryEnd;record.profilerSummaryStatus='resolved';
  }catch(error){record.profilerSummaryStatus='unresolved';record.profilerSummaryReason=String(error?.message??error);}
 };

 const counts=(events,key)=>{const out={};for(const event of events){const name=String(event[key]);out[name]=(out[name]??0)+1;}return out;};
 const summarizeGc=()=>{
  const windows=windowRecords.map(record=>{
   const resolved=Number.isFinite(record.profilerStartElapsedMs)&&Number.isFinite(record.profilerEndElapsedMs);
   return {index:record.index,startStep:record.startStep,endStep:record.endStep,boundarySource:resolved?'profiler-summary':(Number.isFinite(record.startElapsedMs)&&Number.isFinite(record.endElapsedMs)?'host-boundary':null),startElapsedMs:resolved?record.profilerStartElapsedMs:record.startElapsedMs,endElapsedMs:resolved?record.profilerEndElapsedMs:record.endElapsedMs};
  });
  const relations=gcEvents.map((event,index)=>{
   const startTime=event.startTime,duration=event.duration;
   let windowIndex=null,window=null,boundarySource=null;
   for(const candidate of windows){
    if(candidate.boundarySource===null)continue;
    const contained=startTime>=candidate.startElapsedMs&&startTime<=candidate.endElapsedMs;
    const overlaps=startTime<=candidate.endElapsedMs&&startTime+duration>=candidate.startElapsedMs;
    if(contained||overlaps){windowIndex=candidate.index;window={contained,overlaps};boundarySource=candidate.boundarySource;break;}
   }
   let phaseName=null;
   for(const candidate of report.phases)if(startTime>=candidate.startElapsedMs&&startTime<=candidate.endElapsedMs)phaseName=candidate.phase;
   return {index,windowIndex,containedInWindow:window?window.contained:false,overlapsWindow:window?window.overlaps:false,boundarySource,phase:phaseName};
  });
  for(const record of windowRecords){
   const indexes=relations.filter(relation=>relation.windowIndex===record.index).map(relation=>relation.index),events=indexes.map(index=>gcEvents[index]);
   record.gc={count:relations.filter(relation=>relation.windowIndex===record.index&&relation.containedInWindow).length,overlapCount:indexes.length,durationMs:events.reduce((sum,event)=>sum+event.duration,0),byKind:counts(events,'kind'),byFlags:counts(events,'flags')};
  }
  report.windows=windowRecords;
  return {schemaVersion:1,kind:'host-worker-gc-observation',observer:gcObservation??null,flush:gcFlush,clock:'GC entry.startTime, event durations, phase and window boundaries are performance.now() values on the same host-worker time origin',boundaryDefinition:'Containment compares each GC entry startTime with the window startElapsedMs/endElapsedMs taken from the profiler summary record when resolved, otherwise from the outer host boundaries. A window overlap additionally requires startTime+duration>=startElapsedMs. Events crossing a boundary are reported as overlapping and are not split.',rawEventFields:['startTime','duration','kind','flags'],nodeConstants:gcNodeConstants,events:gcEvents,relations,totals:{count:gcEvents.length,durationMs:gcEvents.reduce((sum,event)=>sum+event.duration,0),byKind:counts(gcEvents,'kind'),byFlags:counts(gcEvents,'flags'),containedInWindows:relations.filter(relation=>relation.containedInWindow).length,overlappingWindows:relations.filter(relation=>relation.overlapsWindow).length},windows,limitations:['GC entries describe the host worker isolate only; no target-image instrumentation exists.','duration is Node-reported observed GC wall duration, not exact CPU time and not retained bytes.','PerformanceObserver delivery is asynchronous; the report flushes pending delivery once and disconnects, so events raised afterwards or still undelivered are absent.','No forced GC and no full heap snapshot were used; used/reserved heap values are point-in-time v8 statistics at the declared phase and window boundaries.','Window containment uses the profiler summary startElapsedMs/endElapsedMs when resolved; otherwise the outer host boundary, which also contains profiler file-write time.','An event crossing a boundary is reported as overlapping and is never split or re-attributed.','GC observation perturbs execution; these diagnostics are separate from unprofiled timing samples.']};
 };

 try{
  gcObservation=attachGcObserver();
  const {api,checker}=await phase('startup',async()=>{
   const parserURL=pathToFileURL(request.parserImage.path).href,checkerURL=pathToFileURL(request.checkerImage.path).href;
   const parserSearch=new URL(parserURL).search,checkerSearch=new URL(checkerURL).search;
   if(parserURL!==checkerURL||parserSearch!==''||checkerSearch!=='')throw Error('One actual image/module per role is required');
   const api=(await import(parserURL)).default,checker=(await import(checkerURL)).default;
   if(api!==checker)throw Error('Expected the same parser/checker module instance');
   report.moduleResidency={parserURL,checkerURL,parserSearch,checkerSearch:checkerSearch||null,sameConfiguredPath:request.parserImage.path===request.checkerImage.path,distinctAPI:false,moduleInstances:1,lane:request.role,policy:'One actual compiler image supplies parsing, expansion and checking in each role, matching original throughput residency.',parserImageSha256:typeof request.parserImage?.sha256==='string'?request.parserImage.sha256:null,checkerImageSha256:typeof request.checkerImage?.sha256==='string'?request.checkerImage.sha256:null};
   return {api,checker};
  });
  for(const key of ['check_expanded_start','inspect_checked_start','checker_step'])if(typeof checker[key]!=='function')throw Error('Checker ABI incomplete '+key);
  let modules=[];await phase('load-parse',()=>{
   const seen=new Map(),active=new Set(),observed=new Set();
   const observe=path=>{const real=realpathSync(path);if(!Object.hasOwn(request.inputs,real))throw Error('Unexpected input '+real);observed.add(real);return real;};
   const namespace=(scope,path)=>path==='Base'?'':posix.normalize(isAbsolute(path)?path.replace(/\.bend$/,''):posix.dirname(scope)+'/'+path.replace(/\.bend$/,''));
   const visit=(file,scope)=>{const real=observe(file);if(active.has(real))throw Error('Import cycle');if(seen.has(real)){if(seen.get(real)!==scope)throw Error('Namespace conflict');return;}seen.set(real,scope);active.add(real);
    const parsed=api.parse_with_fuel(fuel(8000000),real,readFileSync(real,'utf8'));if(tag(parsed)!=='FeedbackComplete'||tag(parsed.value.result)!=='ParseSuccess')throw Error('Own parser rejected '+real);const module=parsed.value.result.module;
    for(const top of items(module.declarations))if(tag(top)==='DefTop'&&tag(top.definition.body)==='DefImports')for(const path of items(top.definition.body.paths))if(path.endsWith('.js'))observe(resolve(dirname(real),path));
    for(const imported of items(module.imports)){const path=imported.path;if(path.endsWith('.js'))observe(resolve(dirname(real),path));else if(!path.endsWith('.c'))visit(path==='Base'?resolve(request.repository,'bend2/base.bend'):resolve(dirname(real),path),namespace(scope,path));}
    modules.push(api.parsed_module(scope,module));active.delete(real);
   };visit(request.root,'');if(observed.size!==Object.keys(request.inputs).length)throw Error('Own parser omitted frozen input');report.moduleCount=seen.size;modules=list(modules);
  });
  let expanded=await phase('expand',()=>runTemplateSteps({...api,expand_modules_start:input=>{modules=undefined;return api.expand_modules_start(input);}},modules,{onFinish(_,steps){report.stepCounts.expand=steps;}}));
  if(tag(expanded)!=='ExpandSuccess')throw Error('Own expansion failed');
  const observer={onStep(steps){
   const record=windowRecords[windowIndex];if(!record)return;
   if(steps===record.startStep){
    if(profiler)throw Error('Overlapping profiling windows');
    record.heapStart=heapSnapshot();record.startElapsedMs=record.heapStart.elapsedMs;
    beforeDirs[record.index]=profileDirectories(profileRoot);
    profiler=createCpuProfiler(profileRoot,{role:request.role,checkerImage:request.checkerImage,steps:{start:record.startStep,end:record.endStep}});
    profiler.mark('check-window',{start:record.startStep,end:record.endStep});
   }else if(steps===record.endStep){
    if(!profiler)throw Error('Profiling window end without start');
    profiler.finish();profiler=undefined;
    record.endElapsedMs=performance.now();
    record.heapEnd=heapSnapshot();
    record.hostWallMs=record.endElapsedMs-record.startElapsedMs;
    resolveProfilerSummary(record);
    windowIndex++;
   }
  },onFinish(_,steps){report.stepCounts.check=steps;if(profiler)throw Error('Incomplete profiling window');if(windowIndex!==windowRecords.length)throw Error('Missing profiling windows');},onError(error){try{profiler?.finish(error);}catch(finalizeError){report.profilerFinalizeError=String(finalizeError);}finally{profiler=undefined;}}};
  const checked=await phase('check',()=>runCheckerSteps({...checker,check_expanded_start:input=>{expanded=undefined;return checker.check_expanded_start(input);}},expanded.modules,observer));
  if(tag(checked)!=='CheckSuccess')throw Error('Own checking failed '+JSON.stringify(checked));
  await phase('storage',()=>{
   const source=checked.program.source,words=source.words;if((!Array.isArray(words)&&!(words instanceof Uint32Array))||!Array.isArray(source.counts))throw Error('Unknown word-tape carrier');
