      sampleStopPromise = stopSample('phase-emit-end');
    }
    return;
  }
  if (line.startsWith(BEGIN_PREFIX)) {
    if (!begin) begin = parseProtocol(line, BEGIN_PREFIX);
    return;
  }
  if (line.startsWith(FUEL_PREFIX)) {
    fuel.push(parseProtocol(line, FUEL_PREFIX));
  }
